// Package lalr_logicparser provides an LALR(1) formula parser generated by
// goyacc, mechanically translated from the Python PLY grammar. It is used
// as a cross-validation oracle for the hand-written recursive descent parser.
package lalr_logicparser

import (
	"fmt"

	"github.com/glycerine/goivy/ast"
	"github.com/glycerine/goivy/lalr_logicparser/v12"
	"github.com/glycerine/goivy/lalr_logicparser/v16"
	"github.com/glycerine/goivy/lexer"
)

// Parse dispatches to the appropriate version-specific LALR parser.
func Parse(input string, version lexer.Version) (ast.Node, error) {
	if version[0] < 1 || (version[0] == 1 && version[1] <= 2) {
		return v12.ParseV12(input, version)
	}
	if version[0] == 1 && version[1] <= 6 {
		return v16.ParseV16(input, version)
	}
	return ParseV17(input, version)
}

// ParseV17 parses a formula string using the v1.7+ LALR grammar.
// Returns the AST node, or an error if parsing fails.
func ParseV17(input string, version lexer.Version) (ast.Node, error) {
	lex := newV17LexAdapter(input, version)
	v17Parse(lex)
	if lex.err != "" {
		return nil, fmt.Errorf("LALR parse error: %s", lex.err)
	}
	return lex.result, nil
}

// --- v17LexAdapter: adapter from lexer.Lexer to goyacc's v17Lexer interface ---

// v17LexAdapter implements the v17Lexer interface generated by goyacc.
type v17LexAdapter struct {
	lex    *lexer.Lexer
	result ast.Node
	err    string
}

func newV17LexAdapter(input string, version lexer.Version) *v17LexAdapter {
	return &v17LexAdapter{
		lex: lexer.New(input, version),
	}
}

// Lex returns the next token for goyacc.
func (l *v17LexAdapter) Lex(lval *v17SymType) int {
	tok := l.lex.NextToken()

	switch tok.Type {
	case lexer.EOF:
		return 0
	case lexer.SYMBOL:
		lval.str = tok.Value
		return TOK_PRESYMBOL
	case lexer.VARIABLE:
		lval.str = tok.Value
		return TOK_VARIABLE
	case lexer.LPAREN:
		return TOK_LPAREN
	case lexer.RPAREN:
		return TOK_RPAREN
	case lexer.LB:
		return TOK_LB
	case lexer.RB:
		return TOK_RB
	case lexer.LCB:
		return TOK_LCB
	case lexer.RCB:
		return TOK_RCB
	case lexer.COMMA:
		return TOK_COMMA
	case lexer.SEMI:
		return TOK_SEMI
	case lexer.COLON:
		return TOK_COLON
	case lexer.DOT:
		return TOK_DOT
	case lexer.PLUS:
		return TOK_PLUS
	case lexer.MINUS:
		return TOK_MINUS
	case lexer.TIMES:
		return TOK_TIMES
	case lexer.DIV:
		return TOK_DIV
	case lexer.EQ:
		return TOK_EQ
	case lexer.TILDAEQ:
		return TOK_TILDAEQ
	case lexer.TILDA:
		return TOK_TILDA
	case lexer.LE:
		return TOK_LE
	case lexer.LT:
		return TOK_LT
	case lexer.GE:
		return TOK_GE
	case lexer.GT:
		return TOK_GT
	case lexer.AND:
		return TOK_AND
	case lexer.OR:
		return TOK_OR
	case lexer.ARROW:
		return TOK_ARROW
	case lexer.IFF:
		return TOK_IFF
	case lexer.PTO:
		return TOK_PTO
	case lexer.DOLLAR:
		return TOK_DOLLAR
	case lexer.FORALL:
		return TOK_FORALL
	case lexer.EXISTS:
		return TOK_EXISTS
	case lexer.TRUE:
		return TOK_TRUE
	case lexer.FALSE:
		return TOK_FALSE
	case lexer.OLD:
		return TOK_OLD
	case lexer.THIS:
		return TOK_THIS
	case lexer.ISA:
		return TOK_ISA
	case lexer.IF:
		return TOK_IF
	case lexer.ELSE:
		return TOK_ELSE
	case lexer.GLOBALLY:
		return TOK_GLOBALLY
	case lexer.EVENTUALLY:
		return TOK_EVENTUALLY
	case lexer.WHENNEXT:
		return TOK_WHENNEXT
	case lexer.WHENPREV:
		return TOK_WHENPREV
	case lexer.WHENFIRST:
		return TOK_WHENFIRST
	case lexer.WHENLAST:
		return TOK_WHENLAST
	// Action tokens
	case lexer.ASSUME:
		return TOK_ASSUME
	case lexer.ASSERT:
		return TOK_ASSERT
	case lexer.REQUIRE:
		return TOK_REQUIRE
	case lexer.ENSURE:
		return TOK_ENSURE
	case lexer.ASSIGN:
		return TOK_ASSIGN
	case lexer.VAR:
		return TOK_VAR
	case lexer.LOCAL:
		return TOK_LOCAL
	case lexer.LET:
		return TOK_LET
	case lexer.CALL:
		return TOK_CALL
	case lexer.WHILE:
		return TOK_WHILE
	case lexer.FOR:
		return TOK_FOR
	case lexer.IN:
		return TOK_IN
	case lexer.INVARIANT:
		return TOK_INVARIANT
	case lexer.DECREASES:
		return TOK_DECREASES
	case lexer.RETURNS:
		return TOK_RETURNS
	case lexer.SOME:
		return TOK_SOME
	case lexer.MINIMIZING:
		return TOK_MINIMIZING
	case lexer.MAXIMIZING:
		return TOK_MAXIMIZING
	case lexer.DEBUG:
		return TOK_DEBUG
	case lexer.THUNK:
		return TOK_THUNK
	case lexer.UNPROVABLE:
		return TOK_UNPROVABLE
	case lexer.PROOF:
		return TOK_PROOF
	case lexer.INSTANTIATE:
		return TOK_INSTANTIATE
	case lexer.CARET:
		return TOK_CARET
	case lexer.METHOD:
		return TOK_METHOD
	case lexer.NULL:
		return TOK_NULL
	case lexer.SET:
		return TOK_SET
	case lexer.WITH:
		return TOK_WITH
	// Scenario tokens
	case lexer.SCENARIO:
		return TOK_SCENARIO
	case lexer.BEFORE:
		return TOK_BEFORE
	case lexer.AFTER:
		return TOK_AFTER
	default:
		lval.str = tok.Value
		return TOK_PRESYMBOL
	}
}

// Error is called by goyacc when a parse error occurs.
func (l *v17LexAdapter) Error(s string) {
	l.err = s
}
